preConditionHook:
// THE CLIMACTIC REVERSAL of the chapter's own title: a spike in one direction
// immediately followed by a spike in the opposite direction. A spike is the
// corpus's settled primitive -- StrongTrendBarRun's test, spikeBars consecutive
// with-trend bars whose body is at least bodyFraction of the bar's own range.
//
// THE LONG SIDE IS THE MERGED PSEUDOCODE'S OWN SPELLING: the run ending on THIS
// bar is the DOWN spike, and the older run is the UP spike -- an up move
// reversed down. The short side mirrors it. Brooks's expectation after the pair
// is a transition into a trading range whose eventual breakout runs about the
// height of the FIRST spike; that is a target, not a condition, and is left to
// the exits/targets pass, so the rule is the shape only and a placement's
// direction toggle decides which way it is traded.
//
// THE OLDER SPIKE IS LOCATED RELATIVE TO THE NEWER ONE, not at a fixed lag: its
// newest bar sits at offset spikeBars + ee for ee in 0..gapBars, so ee = 0 is
// the two runs touching and gapBars is how many bars may separate them. A
// pattern over a VARIABLE offset, which no AND of fixed-lag panes reaches --
// the same argument that keeps ConsecutiveClimaxBars whole.
//
// Both runs are all-of-N in the StrongTrendBarRun shape: start true, let a
// failing bar clear the flag, loop unconditionally so EasyLanguage's lack of
// short-circuiting cannot matter. Every scratch value is a localVariables
// entry, never a hook-scope declaration, so the hooks survive a double
// placement; the flags persist across bars and are all reset before use.
//
// Deepest bar touched: 2 * spikeBars + gapBars - 1.
downNow = true;
upNow = true;
for (ii = 0; ii < (int)spikeBars; ++ii) {
    if (el_ge(close[ii], open[ii])) downNow = false;
    if (el_lt(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))) downNow = false;
    if (el_le(close[ii], open[ii])) upNow = false;
    if (el_lt(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))) upNow = false;
}
upBefore = false;
downBefore = false;
for (ee = 0; ee <= (int)gapBars; ++ee) {
    allUp = true;
    allDn = true;
    for (ii = 0; ii < (int)spikeBars; ++ii) {
        bb = (int)spikeBars + ee + ii;
        if (el_le(close[bb], open[bb])) allUp = false;
        if (el_lt(close[bb] - open[bb], bodyFraction * (high[bb] - low[bb]))) allUp = false;
        if (el_ge(close[bb], open[bb])) allDn = false;
        if (el_lt(open[bb] - close[bb], bodyFraction * (high[bb] - low[bb]))) allDn = false;
    }
    if (allUp) upBefore = true;
    if (allDn) downBefore = true;
}
